"""
Телефон сам открывает сайты, поиск, приложения, музыку, видео, карты, звонки и сообщения.

  • «Найди в гугле SAT practice test», «включи lofi на ютубе», «Imagine Dragons в Spotify»,
    «открой habr.com», «где Дордой Плаза на карте», «напиши в WhatsApp…», «позвони +996…».
  • Atlas отвечает голосом и показывает кнопку — она открывает нужное приложение на телефоне
    (YouTube, Spotify, Карты, 2ГИС, WhatsApp, Telegram, Instagram, TikTok, Gmail…), а если его нет — сайт.
  • Компьютер — только когда о нём сказали («включи музыку на компе») или дело в нём самом
    (его громкость, файлы, программы). Без слова «компьютер» Atlas открывает на телефоне.

    python apply_phone_actions.py
    python apply_phone_actions.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'cloud/atlas_cloud.py': '1fb466271a04a4b629e36243a9899c50b1b44f0ad27fd1958470355d313b0897', 'phone/server.py': 'f279a323cf8799955a3fc3590958ac78ef767951935beecfe187cd6d61c33b8f', 'phone/static/index.html': '3ed80106bcb68742beae118e34d9cdc68d11031db1975d5494b0e63da66b9900', 'phone/static/sw.js': 'fd8423268ca23c6a90900c9213609799b4507119d9b9237eecef3fe2caa9a8f3', 'tests/test_cloud_brain.py': 'b96f9c7e6509141539672210352cb318ad7078e7d3c3949aeecff67779bddb87', 'tests/test_phone.py': 'b510d426c6e356e27881d112514d42d82533bbf5068ba1cdd28fa9684c9847e8', 'core/phone_actions.py': None}
NEW = {'cloud/atlas_cloud.py': '', 'phone/server.py': '', 'phone/static/index.html': '', 'phone/static/sw.js': '', 'tests/test_cloud_brain.py': '', 'tests/test_phone.py': '', 'core/phone_actions.py': ''}
TAG = "backup_phoneact_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p('core/phone_actions.py')) and 'def open_on_phone' in open(p('core/phone_actions.py'), encoding="utf-8").read():
    sys.exit("Уже установлено.")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ open_on_phone: сайты, поиск, YouTube, Spotify, карты, 2ГИС, мессенджеры, звонки — на самом телефоне")
print("  ✓ на компьютер — только когда его назвали или дело в нём самом")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push — Render обновится сам за 3–5 минут.")
print("На телефоне полностью закрой и открой Atlas, чтобы подтянулась новая версия.")

